#!/usr/bin/env node
/**
 * `prisma generate`, skipped when the client in src/generated already comes from
 * this schema and this Prisma version (#370). Generating rewrites every file of
 * the client in src/, and the running dev server (`nest start --watch`) restarts
 * on that, so `pnpm check-all` (`backend build`) took the backend down for
 * 30–60 s while someone was using the app.
 *
 * What the client was generated from is read from the client itself (its
 * `inlineSchema` and `clientVersion`), never from a stamp of our own: the client
 * is also generated by `start:dev`, `prisma migrate dev` and CI, and a stamp
 * they don't update could call a client from another branch up to date (review
 * #395). A clean checkout (CI, the Docker image) has no client and generates.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const backend = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const generatedClass = path.join(backend, 'src/generated/prisma/internal/class.ts');

const require = createRequire(path.join(backend, 'package.json'));
const prismaManifest = require.resolve('prisma/package.json');
const { version: prismaVersion, bin } = require(prismaManifest);
const prismaCli = path.join(
  path.dirname(prismaManifest),
  typeof bin === 'string' ? bin : bin.prisma,
);

/** A string property of the generated client's config, e.g. `"clientVersion": "7.10.1"`. */
const generatedString = (source, key) => {
  const match = source.match(new RegExp(`"${key}":\\s*("(?:[^"\\\\]|\\\\.)*")`));
  return match ? JSON.parse(match[1]) : undefined;
};

const normalise = (text) => text.replace(/\r\n/g, '\n');

const isUpToDate = () => {
  if (!existsSync(generatedClass)) return false;
  const generated = readFileSync(generatedClass, 'utf8');
  const schema = readFileSync(path.join(backend, 'prisma/schema.prisma'), 'utf8');
  const inlineSchema = generatedString(generated, 'inlineSchema');
  return (
    generatedString(generated, 'clientVersion') === prismaVersion &&
    inlineSchema !== undefined &&
    normalise(inlineSchema) === normalise(schema)
  );
};

if (isUpToDate()) {
  console.log('Prisma Client matches prisma/schema.prisma, not generated again.');
} else {
  // the CLI through this node: no shell, the same on Windows and in the image
  execFileSync(process.execPath, [prismaCli, 'generate'], {
    cwd: backend,
    stdio: 'inherit',
  });
}
